/** Swing amplitude in radians. */
export const AMPLITUDE = 0.6;
/** Animation period in seconds (full left swing + mirrored right swing). */
export const PERIOD = 2;

/**
 * Build a Newton's cradle: a frame with `balls` pivot groups hinged at the
 * frame's top bar. Each pivot hangs a string of length `stringLen` with a
 * ball mesh at its end. Deterministic — no clocks, no randomness; all motion
 * is driven exclusively through animateCradle(cradle, t).
 *
 * @param {{ balls?: number, stringLen?: number }} [opts]
 * @returns {{
 *   root: THREE.Group,
 *   frame: THREE.Group,
 *   pivots: THREE.Group[],
 *   balls: THREE.Mesh[]
 * }}
 */
export function buildCradle({ balls = 5, stringLen = 4 } = {}) {
  if (!Number.isInteger(balls) || balls < 1) {
    throw new RangeError(`balls must be a positive integer, got ${balls}`);
  }
  if (!(stringLen > 0)) {
    throw new RangeError(`stringLen must be positive, got ${stringLen}`);
  }

  const root = new THREE.Group();
  root.name = 'cradle-root';

  // ---- Frame -------------------------------------------------------------
  const frame = new THREE.Group();
  frame.name = 'frame';
  root.add(frame);

  const spacing = 1.1;                       // distance between adjacent hinges
  const barWidth = (balls + 2) * spacing;    // top bar extends past outermost pivots
  const hingeY = 6;                          // height of the top bar

  const frameMat = new THREE.MeshStandardMaterial({ color: 0x8a8f98, metalness: 0.7, roughness: 0.35 });
  const ballMat = new THREE.MeshStandardMaterial({ color: 0xc9a227, metalness: 0.9, roughness: 0.2 });

  const base = new THREE.Mesh(new THREE.BoxGeometry(barWidth + 1, 0.3, 2), frameMat);
  base.position.y = 0.15;
  base.name = 'frame-base';
  frame.add(base);

  for (const sideX of [-1, 1]) {
    const legHeight = hingeY;
    const leg = new THREE.Mesh(new THREE.BoxGeometry(0.25, legHeight, 0.25), frameMat);
    leg.position.set(sideX * (barWidth / 2 - 0.125), legHeight / 2, 0);
    leg.name = `frame-leg-${sideX > 0 ? 'right' : 'left'}`;
    frame.add(leg);
  }

  const bar = new THREE.Mesh(new THREE.BoxGeometry(barWidth, 0.25, 0.25), frameMat);
  bar.position.y = hingeY;
  bar.name = 'frame-top-bar';
  frame.add(bar);

  // ---- Pivots, strings, balls ---------------------------------------------
  const pivots = [];
  const ballMeshes = [];
  const startX = -((balls - 1) / 2) * spacing;

  const stringGeom = new THREE.CylinderGeometry(0.02, 0.02, stringLen, 6);
  stringGeom.translate(0, -stringLen / 2, 0); // hang downward from the hinge

  for (let i = 0; i < balls; i++) {
    const pivot = new THREE.Group();
    pivot.name = `pivot-${i}`;
    pivot.position.set(startX + i * spacing, hingeY + 0.125, 0); // hinge at the top bar
    frame.add(pivot);
    pivots.push(pivot);

    const string = new THREE.Mesh(stringGeom, new THREE.MeshBasicMaterial({ color: 0x333333 }));
    string.name = `string-${i}`;
    pivot.add(string);

    const radius = spacing / 2 - 0.03;
    const ballMesh = new THREE.Mesh(
      new THREE.SphereGeometry(radius, 32, 32),
      ballMat.clone()
    );
    ballMesh.name = `ball-${i}`;
    ballMesh.position.y = -stringLen; // ball center hangs stringLen below the hinge
    pivot.add(ballMesh);
    ballMeshes.push(ballMesh);
  }

  return { root, frame, pivots, balls: ballMeshes };
}

/**
 * Pose the cradle at time t (seconds). Idealized momentum transfer:
 * during the first half of each period only the LEFTMOST pivot swings to
 * angle A*sin(PI*t') from its raised (positive-z-rotation) side; during the
 * second half only the RIGHTMOST pivot mirrors it on the opposite side.
 * Every other pivot is exactly zero. Pure function of t — deterministic and
 * periodic with period PERIOD = 2.
 *
 * @param {ReturnType<typeof buildCradle>} cradle
 * @param {number} t time in seconds
 * @returns {ReturnType<typeof buildCradle>} the same cradle, mutated in place
 */
export function animateCradle(cradle, t) {
  const { pivots } = cradle;
  const tp = ((t % PERIOD) + PERIOD) % PERIOD; // fold into [0, PERIOD)

  for (const pivot of pivots) {
    pivot.rotation.z = 0;
  }

  if (tp < PERIOD / 2) {
    // First half: leftmost ball swings out on its raised side.
    pivots[0].rotation.z = AMPLITUDE * Math.sin(Math.PI * tp);
  } else {
    // Second half: rightmost ball mirrors it on the opposite side.
    pivots[pivots.length - 1].rotation.z =
      -AMPLITUDE * Math.sin(Math.PI * (tp - PERIOD / 2));
  }

  return cradle;
}
"})
