result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/cradle.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildCradle, animateCradle, AMPLITUDE, PERIOD } from '../src/cradle.js';

const EPS = 1e-9;

describe('buildCradle', () => {
  it('creates the requested number of pivots and balls', () => {
    const c = buildCradle({ balls: 5, stringLen: 4 });
    expect(c.pivots).toHaveLength(5);
    expect(c.balls).toHaveLength(5);
  });

  it('honors custom options', () => {
    const c = buildCradle({ balls: 3, stringLen: 2 });
    expect(c.pivots).toHaveLength(3);
    expect(c.balls[0].position.y).toBe(-2);
  });
});

describe('animateCradle', () => {
  it('at t = 0.5 only the leftmost pivot is at +0.6 rad', () => {
    const c = buildCradle();
    animateCradle(c, 0.5);
    expect(c.pivots[0].rotation.z).toBeCloseTo(+0.6, 9);
    for (let i = 1; i < c.pivots.length; i++) {
      expect(c.pivots[i].rotation.z).toBe(0); // exactly zero, not approximately
    }
  });

  it('at t = 1.5 only the rightmost pivot is at -0.6 rad', () => {
    const c = buildCradle();
    animateCradle(c, 1.5);
    expect(c.pivots[c.pivots.length - 1].rotation.z).toBeCloseTo(-0.6, 9);
    expect(c.pivots[0].rotation.z).toBeCloseTo(0, 9);
    for (let i = 1; i < c.pivots.length - 1; i++) {
      expect(c.pivots[i].rotation.z).toBe(0);
    }
  });

  it('is exactly PERIOD-periodic across sampled times', () => {
    const a = buildCradle();
    const b = buildCradle();
    for (let k = 0; k < 10; k++) {
      const t = (k / 10) * PERIOD; // 10 samples over one period
      animateCradle(a, t);
      animateCradle(b, t + PERIOD);
      for (let i = 0; i < a.pivots.length; i++) {
        expect(a.pivots[i].rotation.z).toBeCloseTo(b.pivots[i].rotation.z, 9);
      }
    }
  });

  it('is zero at phase boundaries (t = 0, 1, 2)', () => {
    const c = buildCradle();
    for (const t of [0, 1, 2]) {
      animateCradle(c, t);
      for (const p of c.pivots) {
        expect(p.rotation.z).toBeCloseTo(0, 9);
      }
    }
  });
});

describe('geometry: balls hang stringLen below their pivots', () => {
  it('world y of each ball equals world y of its pivot minus stringLen', () => {
    const stringLen = 4;
    const scene = new THREE.Scene();
    const c = buildCradle({ balls: 5, stringLen });
    scene.add(c.root);

    animateCradle(c, 0); // rest pose: all strings vertical
    c.root.updateMatrixWorld(true);

    for (let i = 0; i < c.pivots.length; i++) {
      const pivotY = new THREE.Vector3();
      c.pivots[i].getWorldPosition(pivotY);
      const ballY = new THREE.Vector3();
      c.balls[i].getWorldPosition(ballY);
      expect(ballY.y).toBeCloseTo(pivotY.y - stringLen, 9);
    }
  });

  it('holds at a mid-swing pose too (rigid string length is invariant)', () => {
    const stringLen = 3;
    const scene = new THREE.Scene();
    const c = buildCradle({ balls: 5, stringLen });
    scene.add(c.root);

    animateCradle(c, 0.25);
    c.root.updateMatrixWorld(true);

    for (let i = 0; i < c.pivots.length; i++) {
      const pivotY = new THREE.Vector3();
      c.pivots[i].getWorldPosition(pivotY);
      const ballY = new THREE.Vector3();
      c.balls[i].getWorldPosition(ballY);
      expect(ballY.y).toBeCloseTo(pivotY.y - stringLen, 9);
    }
  });
});
"})
